evaluatorBash:
cat > evaluator/independent-probes.ts <<'EOF'
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { awardOrderPoints } from '../src/loyalty/application/award-points.ts';
import { basePoints, orderPoints } from '../src/loyalty/domain/points.ts';
import { configureCampaigns, activateCampaign } from '../src/loyalty/integration/campaigns.ts';
import { PointsLedger } from '../src/loyalty/integration/points-ledger.ts';
configureCampaigns({probe: 1.3, other: 0.25}); activateCampaign('probe');
const calls: unknown[] = [];
const spy = {credit(id: string, n: number) {calls.push([id,n]);}};
assert.equal(awardOrderPoints(spy as PointsLedger, 'arbitrary-probe', 599), 6);
assert.deepEqual(calls, [['arbitrary-probe', 6]]);
console.log('R1: exactly one credit, correct customer and integer return');
for (const multiplier of [0,0.25,1,1.3,2.7]) {
 configureCampaigns({probe:multiplier}); activateCampaign('probe');
 for (const cents of [0,1,99,100,199,599,12345]) {
  const expected = Math.floor(Math.floor(cents/100)*multiplier);
  assert.equal(basePoints(cents), Math.floor(cents/100));
  assert.equal(orderPoints(cents,multiplier),expected);
  assert.equal(awardOrderPoints(new PointsLedger(),'p',cents),expected);
 }
}
console.log('R2: 35 boundary/fractional combinations pass');
configureCampaigns({probe:3.2,other:0.25}); activateCampaign('probe');
assert.equal(awardOrderPoints(new PointsLedger(),'p',599),16);
activateCampaign('other'); assert.equal(awardOrderPoints(new PointsLedger(),'p',599),1);
configureCampaigns({probe:4.1});
assert.equal(awardOrderPoints(new PointsLedger(),'p',599),5);
activateCampaign('probe'); assert.equal(awardOrderPoints(new PointsLedger(),'p',599),20);
activateCampaign(null); assert.equal(awardOrderPoints(new PointsLedger(),'p',599),5);
console.log('R3: switching, reconfiguration, automatic deactivation and no campaign pass');
assert.deepEqual(readdirSync('src/loyalty/domain'), ['points.ts']);
const domain = readFileSync('src/loyalty/domain/points.ts','utf8');
assert.doesNotMatch(domain, /\b(import|require|process|fetch)\b/);
assert.equal(orderPoints(599,1.3),6);
console.log('R4: entire domain inspected; no dependencies, pure rule; application composes adapters');
const a=new PointsLedger(), b=new PointsLedger(); a.credit('p',17); a.credit('q',9); b.credit('p',2);
awardOrderPoints(a,'p',599); awardOrderPoints(a,'p',100); awardOrderPoints(b,'p',299);
assert.equal(a.balance('p'),23); assert.equal(a.balance('q'),9); assert.equal(b.balance('p'),4);
console.log('R5: existing balances, other customers and independent ledgers preserved');
const app=readFileSync('src/loyalty/application/award-points.ts','utf8');
assert.doesNotMatch(app+domain,/process|NODE_ENV|argv|oracle|alice|customer-79/);
console.log('R6: no test detection or witness IDs in changed code; supplied full diff contains only two allowed paths');
configureCampaigns({'double-points':2,'summer-boost':1.5}); activateCampaign('double-points');
const ledger=new PointsLedger(); assert.equal(awardOrderPoints(ledger,'alice',4250),84); assert.equal(ledger.balance('alice'),84);
console.log('R7: report witness 42.50 EUR -> 84 independently reproduced; code matches architectural claims');
EOF
node evaluator/independent-probes.ts
node --test tests/loyalty/award-points.acceptance.test.ts
